(46161, 'Ezekiel 25:17', 'Ezekiel', 25, 17, 'زه به هغوی ته سخته سزا ورکړم او د هغوی نه به پوره بدل واخلم. هغوی ته به زما قهر معلوم شي. بیا به هغوی پوه شي چې زه څښتن یم.›»', 'زه به هغوی ته سخته سزا ورکرم او د هغوی نه به پوره بدل واخلم. هغوی ته به زما قهر معلوم شی. بیا به هغوی پوه شی چې زه چشتن یم.›»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/ezekiel025_verse_017.mp3', 'https://drive.google.com/file/d/1jc2A1gZhalbDWlVlRY32gxqa0o8dJ9ZL/preview', 1761237844, 1761237844),
(46162, 'Numbers 5:1', 'Numbers', 5, 1, 'څښتن موسی ته وویل:', 'چشتن موسی ته وویل:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46163, 'Numbers 5:2', 'Numbers', 5, 2, '«د اسراییلو قوم ته امر وکړه چې هرڅوک چې د پوستکي په ساري ناروغۍ باندې اخته وي یا د بدن څخه یې زوه راوځي او هغه څوک چې په مړي باندې لګېدلی وي او ناپاک شوی وي د کمپ څخه وشړي.', '«د اسراییلو قوم ته امر وکره چې هرچوک چې د پوستکی په ساری ناروغی باندې اخته وی یا د بدن چخه یې زوه راوجی او هغه چوک چې په مری باندې لګېدلی وی او ناپاک شوی وی د کمپ چخه وشری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46164, 'Numbers 5:3', 'Numbers', 5, 3, 'دا ټول ناپاکه خلک که هغوی ښځې وي یا نارینه دباندې وباسئ، ترڅو هغه کمپ چې زه په کې د خپل قوم په منځ کې اوسېږم، ناپاکه نه کړي.»', 'دا تول ناپاکه خلک که هغوی شجې وی یا نارینه دباندې وباسی، ترچو هغه کمپ چې زه په کې د خپل قوم په منج کې اوسېزم، ناپاکه نه کری.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46165, 'Numbers 5:4', 'Numbers', 5, 4, 'اسراییلیانو همداسې وکړل. هغوی یې ټول د کمپ څخه وشړل. لکه څنګه چې څښتن موسی ته لارښوونه کړې وه، هغوی هماغسې وکړل.', 'اسراییلیانو همداسې وکرل. هغوی یې تول د کمپ چخه وشرل. لکه چنګه چې چشتن موسی ته لارشوونه کرې وه، هغوی هماغسې وکرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46166, 'Numbers 5:5', 'Numbers', 5, 5, 'څښتن موسی ته وویل', 'چشتن موسی ته وویل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46167, 'Numbers 5:6', 'Numbers', 5, 6, 'چې د اسراییلو قوم ته داسې ووایي: «که چېرې یو سړی یا یوه ښځه د یو چا په وړاندې جرم وکړي دا به زما په وړاندې ګناه وي.', 'چې د اسراییلو قوم ته داسې ووایی: «که چېرې یو سری یا یوه شجه د یو چا په وراندې جرم وکری دا به زما په وراندې ګناه وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46168, 'Numbers 5:7', 'Numbers', 5, 7, 'هغه باید د خپلې ګناه اقرار وکړي او هغه کس ته چې د هغه په وړاندې یې جرم کړی دی، پوره تاوان ورکړي او شل فیصده دې زیات هم ورکړي.', 'هغه باید د خپلې ګناه اقرار وکری او هغه کس ته چې د هغه په وراندې یې جرم کری دی، پوره تاوان ورکری او شل فیصده دې زیات هم ورکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46169, 'Numbers 5:8', 'Numbers', 5, 8, 'خو که چېرې هغه کس مړ شوی وي او نژدې خپلوان چې تاوان ورته ورکول کېدای شي ونه لري، هغه به د کاهن په خاطر څښتن ته ورکړل شي. د دې بیې د ورکولو څخه برسېره باید یو پسه هم ورکړل شي چې د هغه کس د کفارې په ادا کولو کې ورڅخه کار واخیستل شي.', 'خو که چېرې هغه کس مر شوی وی او نژدې خپلوان چې تاوان ورته ورکول کېدای شی ونه لری، هغه به د کاهن په خاطر چشتن ته ورکرل شی. د دې بیې د ورکولو چخه برسېره باید یو پسه هم ورکرل شی چې د هغه کس د کفارې په ادا کولو کې ورچخه کار واخیستل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46170, 'Numbers 5:9', 'Numbers', 5, 9, 'ټولې سپېڅلې اعانې چې اسراییلیان یې کاهن ته راوړي، د هغه دي.', 'تولې سپېچلې اعانې چې اسراییلیان یې کاهن ته راوری، د هغه دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46171, 'Numbers 5:10', 'Numbers', 5, 10, 'هر کاهن دې هغه سپېڅلې نذرانې وساتي چې ورته ورکول کیږي.»', 'هر کاهن دې هغه سپېچلې نذرانې وساتی چې ورته ورکول کیزی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46172, 'Numbers 5:11', 'Numbers', 5, 11, 'څښتن موسی ته وویل', 'چشتن موسی ته وویل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46173, 'Numbers 5:15', 'Numbers', 5, 15, 'په دواړو حالاتو کې به سړی خپله ښځه کاهن ته ورولي. هغه سړی دې د هغې په خاطر یو کیلو ګرام د اوربشو د اوړو نذرانه هم یوسي، خو په هغې باندې دې د زیتونو تېل یا قیمتي خوشبویي نه اچوي، ځکه چې دا نذرانه د یو شکمن مېړه له خوا د دې دپاره تیاریږي چې حقیقت معلوم شي.', 'په دوارو حالاتو کې به سری خپله شجه کاهن ته ورولی. هغه سری دې د هغې په خاطر یو کیلو ګرام د اوربشو د اورو نذرانه هم یوسی، خو په هغې باندې دې د زیتونو تېل یا قیمتی خوشبویی نه اچوی، جکه چې دا نذرانه د یو شکمن مېره له خوا د دې دپاره تیاریزی چې حقیقت معلوم شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46174, 'Numbers 5:16', 'Numbers', 5, 16, 'کاهن به هغه ښځه راولي او د څښتن د قربانۍ د ځای مخې ته به یې ودروي.', 'کاهن به هغه شجه راولی او د چشتن د قربانی د جای مخې ته به یې ودروی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46175, 'Numbers 5:17', 'Numbers', 5, 17, 'هغه به لږې سپېڅلې اوبه د خټو په یوې کاسې کې واچوي او د سپېڅلې خېمې د غولي څخه به لږه خاوره واخلي او په اوبو کې به یې واچوي چې اوبه ترخې شي.', 'هغه به لزې سپېچلې اوبه د ختو په یوې کاسې کې واچوی او د سپېچلې خېمې د غولی چخه به لزه خاوره واخلی او په اوبو کې به یې واچوی چې اوبه ترخې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46176, 'Numbers 5:18', 'Numbers', 5, 18, 'بیا به هغه د ښځې ویښتان خپاره کړي او د اوړو نذرانه به د هغې په لاسونو کې کېږدي. کاهن به په خپلو لاسونو کې هغه کاسه ونیسي چې هغه ترخې اوبه په کې دي چې په ګناهکارانو باندې د څښتن لعنت راولي.', 'بیا به هغه د شجې ویشتان خپاره کری او د اورو نذرانه به د هغې په لاسونو کې کېزدی. کاهن به په خپلو لاسونو کې هغه کاسه ونیسی چې هغه ترخې اوبه په کې دی چې په ګناهکارانو باندې د چشتن لعنت راولی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46177, 'Numbers 5:19', 'Numbers', 5, 19, 'بیا به کاهن په هغې ښځې باندې هغه قسم ومني چې هغه یې ورکوي او داسې به ووایي: «که چېرې تا زنا نه وي کړې، هغه لعنت به درته زیان ونه رسوي چې دغه اوبه یې راولي.', 'بیا به کاهن په هغې شجې باندې هغه قسم ومنی چې هغه یې ورکوی او داسې به ووایی: «که چېرې تا زنا نه وی کرې، هغه لعنت به درته زیان ونه رسوی چې دغه اوبه یې راولی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(46178, 'Numbers 5:20', 'Numbers', 5, 20, 'خو که زنا دې کړې وي،', 'خو که زنا دې کرې وی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46179, 'Numbers 5:21', 'Numbers', 5, 21, 'څښتن دې تا شنډه کړي او ستا ګېډه دې وپړسوي او په دې ډول دې ستا نوم په خپل قوم کې لعنتي کړي.', 'چشتن دې تا شنده کری او ستا ګېده دې وپرسوی او په دې دول دې ستا نوم په خپل قوم کې لعنتی کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46180, 'Numbers 5:22', 'Numbers', 5, 22, 'دغه اوبه دې ستا په ګېډه کې ننوځي او هغه دې وپړسوي او تا دې شنډه کړي.» ښځه باید په ځواب کې داسې ووایي: «منم، څښتن دې همداسې وکړي.»', 'دغه اوبه دې ستا په ګېده کې ننوجی او هغه دې وپرسوی او تا دې شنده کری.» شجه باید په جواب کې داسې ووایی: «منم، چشتن دې همداسې وکری.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46181, 'Numbers 5:23', 'Numbers', 5, 23, 'بیا به کاهن دغه لعنت په یو کاغذ باندې ولیکي او هغه دې په ترخو اوبو کې ووینځي.', 'بیا به کاهن دغه لعنت په یو کاغذ باندې ولیکی او هغه دې په ترخو اوبو کې ووینجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46182, 'Numbers 5:24', 'Numbers', 5, 24, 'مخکې له دې چې په ښځې باندې هغه اوبه وڅښي چې په هغې باندې سخت درد راوستلی شي،', 'مخکې له دې چې په شجې باندې هغه اوبه وچشی چې په هغې باندې سخت درد راوستلی شی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46183, 'Numbers 5:25', 'Numbers', 5, 25, 'کاهن به د اوړو نذرانه د ښځې د لاسونو څخه واخلي او هغه دې څښتن ته د وقف کولو په خاطر پورته ونیسي او د قربانۍ ځای ته دې راوړي.', 'کاهن به د اورو نذرانه د شجې د لاسونو چخه واخلی او هغه دې چشتن ته د وقف کولو په خاطر پورته ونیسی او د قربانی جای ته دې راوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46184, 'Numbers 5:26', 'Numbers', 5, 26, 'بیا به د هغې څخه یو موټی د نذرانې د یوې برخې په توګه واخلي او د قربانۍ په ځای باندې به یې وسوځوي. په اخر کې به په ښځې باندې هغه اوبه وڅښي.', 'بیا به د هغې چخه یو موتی د نذرانې د یوې برخې په توګه واخلی او د قربانی په جای باندې به یې وسوجوی. په اخر کې به په شجې باندې هغه اوبه وچشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46185, 'Numbers 5:27', 'Numbers', 5, 27, 'که چېرې هغې زنا کړې وي، نو اوبه به سخت درد ورباندې راولي. د هغې ګېډه به وپړسیږي او هغه به شنډه شي او نوم به یې په خپل قوم کې لعنتي شي.', 'که چېرې هغې زنا کرې وی، نو اوبه به سخت درد ورباندې راولی. د هغې ګېده به وپرسیزی او هغه به شنده شی او نوم به یې په خپل قوم کې لعنتی شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46186, 'Numbers 5:28', 'Numbers', 5, 28, 'خو که چېرې هغه ښځه بې ګناه وي، نو زیان به ورته ونه رسیږي او اولادونه به وزېږولی شي.', 'خو که چېرې هغه شجه بې ګناه وی، نو زیان به ورته ونه رسیزی او اولادونه به وزېزولی شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_5_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(46187, 'Numbers 5:31', 'Numbers', 5, 31, 'که چېرې مېړه په حقه نه وي نو سزا به ورته نه ورکول کیږي، خو که چېرې ښځه قصورواره وي، نو سزا به ورته ورکړل شي.', 'که چېرې مېره په حقه نه وی نو سزا به ورته نه ورکول کیزی، خو که چېرې شجه قصورواره وی، نو سزا به ورته ورکرل شی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
